import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百二十二章 除灭烦恼和痛苦","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/222第二百二十二章 除灭烦恼和痛苦.md","filePath":"meditation/巴利文大藏经/222第二百二十二章 除灭烦恼和痛苦.md"}'),_={name:"meditation/巴利文大藏经/222第二百二十二章 除灭烦恼和痛苦.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二百二十二章-除灭烦恼和痛苦" tabindex="-1">第二百二十二章 除灭烦恼和痛苦 <a class="header-anchor" href="#第二百二十二章-除灭烦恼和痛苦" aria-label="Permalink to &quot;第二百二十二章 除灭烦恼和痛苦&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应8经/由于执取的战慄经第二(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！如来现在要教导你们：由执着生起的忧愁、悲伤、苦闷、忧虑、绝望、恐惧是如何形成发生的？如何除灭由执着生起的忧愁、悲伤、苦闷、忧虑、绝望、恐惧？你们要认真的听，你们要仔细的思考，如来要开始说法了。”</p><p>出家弟子们回答：“世尊，我们会认真听您说法的，我们会仔细的思考的，恭请世尊您为我们说法。”</p><p>佛陀说：“比丘们（出家人）！由执着生起的忧愁、悲伤、苦闷、忧虑、绝望、恐惧是如何形成发生的呢？那些没有受到如来教导的世间人，他们会认为：「物质事物是我所拥有的，我就是这个物质身体，这个物质身体就是真实不变的我。」简单的说就是，他们会认为：「这是我的，我就是这个，这就是真实不变的我。」当他们的物质身体发生变化的时候，当他们的物质身体生病、衰老、临死的时候，当他们拥有的物质事物发生变化的时候，当他们拥有的物质事物衰败、灭亡、消失的时候，当他们失去物质事物的时候，他们就会由此生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧。就是因为他们贪爱、执着、挂念物质身体、物质事物，所以当物质身体生病、衰老、临死的时候，当物质事物衰败、灭亡、消失的时候，当他们失去物质事物的时候，他们就会产生烦恼和痛苦。</p><p>比丘们！同样的道理，那些没有受到如来教导的世间人，他们会认为：「感受、念想、行为、认识、分别、判断是我所拥有的，我就是这个感受、念想、行为、认识、分别、判断，这个感受、念想、行为、认识、分别、判断就是真实不变的我。」简单的说就是，他们会认为：「这是我的，我就是这个，这就是真实不变的我。」当他们的感受、念想、行为、认识、分别、判断发生变化的时候，当他们的感受、念想、行为、认识、分别、判断让他们不满意、不快乐、不开心的时候，他们就会由此生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧。就是因为他们贪爱、执着、挂念让他们满意、快乐、开心的感受、念想、行为、认识、分别、判断。所以当他们的感受、念想、行为、认识、分别、判断让他们不满意、不快乐、不开心的时候，他们就会产生烦恼和痛苦。</p><p>比丘们！这就是由执着生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧的过程。</p><p>比丘们！如何除灭由执着生起的忧愁、悲伤、苦闷、忧虑、绝望、恐惧呢？那些已经受到如来教导的圣弟子们，他们会认为：「物质事物不是我所拥有的，我不是这个物质身体，这个物质身体不是真实不变的我。」简单的说就是，他们会认为：「这不是我的，我不是这个，这不是真实不变的我。」当他们的物质身体发生变化的时候，当他们的物质身体生病、衰老、临死的时候，当他们拥有的物质事物发生变化的时候，当他们拥有的物质事物衰败、灭亡、消失的时候，当他们失去物质事物的时候，他们就不会由此生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧。就是因为他们不贪爱、不执着、不挂念物质身体、物质事物，所以当物质身体生病、衰老、临死的时候，当物质事物衰败、灭亡、消失的时候，当他们失去物质事物的时候，他们就不会产生烦恼和痛苦。</p><p>比丘们！同样的道理，那些已经受到如来教导的圣弟子们，他们会认为：「感受、念想、行为、认识、分别、判断不是我所拥有的，我不是这个感受、念想、行为、认识、分别、判断，这个感受、念想、行为、认识、分别、判断不是真实不变的我。」简单的说就是，他们会认为：「这不是我的，我不是这个，这不是真实不变的我。」当他们的感受、念想、行为、认识、分别、判断发生变化的时候，当他们的感受、念想、行为、认识、分别、判断让他们不满意、不快乐、不开心的时候，他们就不会由此生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧。就是因为他们不贪爱、不执着、不挂念让他们满意、快乐、开心的感受、念想、行为、认识、分别、判断。所以当他们的感受、念想、行为、认识、分别、判断让他们不满意、不快乐、不开心的时候，他们就不会产生烦恼和痛苦。</p><p>比丘们！这就是除灭由执着生起忧愁、悲伤、苦闷、忧虑、绝望、恐惧的过程。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',12)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
